Subject: [PATCH] wayland: Send window geometries on other virtual desktops

With per-desktop tiling a window on several desktops can sit in another
tile on each of them, but window management clients only got its current
geometry. Send the geometry it takes on each desktop where it differs.

CCBUG: 506056
---
 src/tiles/tile.cpp                     | 11 +++++++
 src/wayland/plasmawindowmanagement.cpp | 35 +++++++++++++++++++-
 src/wayland/plasmawindowmanagement.h   |  6 ++++
 src/window.cpp                         | 45 ++++++++++++++++++++++++++
 src/window.h                           |  1 +
 5 files changed, 97 insertions(+), 1 deletion(-)

diff --git a/src/tiles/tile.cpp b/src/tiles/tile.cpp
index b6cf27b20c..47b4385059 100644
--- a/src/tiles/tile.cpp
+++ b/src/tiles/tile.cpp
@@ -33,6 +33,17 @@ Tile::Tile(TileManager *tiling, Tile *parent)
     }
     connect(Workspace::self(), &Workspace::configChanged, this, &Tile::windowGeometryChanged);
     connect(Workspace::self(), &Workspace::windowRemoved, this, &Tile::unmanage);
+    connect(this, &Tile::windowGeometryChanged, this, [this]() {
+        for (Window *window : std::as_const(m_windows)) {
+            window->updateVirtualDesktopGeometries();
+        }
+    });
+    connect(this, &Tile::windowAdded, this, [](Window *window) {
+        window->updateVirtualDesktopGeometries();
+    });
+    connect(this, &Tile::windowRemoved, this, [](Window *window) {
+        window->updateVirtualDesktopGeometries();
+    });
 }

 Tile::~Tile()
