+    QHash<QString, Rect> virtualDesktopGeometries;
     bool mapped = false;

 protected:
@@ -418,6 +420,12 @@ void PlasmaWindowInterfacePrivate::sendInitialState(Resource *resource)
         send_client_geometry(resource->handle, clientGeometry.x(), clientGeometry.y(), clientGeometry.width(), clientGeometry.height());
     }

+    if (resource->version() >= ORG_KDE_PLASMA_WINDOW_VIRTUAL_DESKTOP_GEOMETRY_SINCE_VERSION) {
+        for (const auto &[desktopId, desktopGeometry] : virtualDesktopGeometries.asKeyValueRange()) {
+            send_virtual_desktop_geometry(resource->handle, desktopId, desktopGeometry.x(), desktopGeometry.y(), desktopGeometry.width(), desktopGeometry.height());
+        }
+    }
+
     if (resource->version() >= ORG_KDE_PLASMA_WINDOW_MAPPED_SINCE_VERSION) {
         if (mapped) {
             send_mapped(resource->handle);
@@ -1146,6 +1154,31 @@ void PlasmaWindowInterfacePrivate::setClientGeometry(const Rect &geometry)
     }
 }

+void PlasmaWindowInterface::setVirtualDesktopGeometry(const QString &desktopId, const Rect &geometry)
+{
+    d->setVirtualDesktopGeometry(desktopId, geometry);
+}
+
+void PlasmaWindowInterfacePrivate::setVirtualDesktopGeometry(const QString &desktopId, const Rect &geometry)
+{
+    if (geometry.isValid()) {
+        if (virtualDesktopGeometries.value(desktopId) == geometry) {
+            return;
+        }
+        virtualDesktopGeometries.insert(desktopId, geometry);
+    } else if (!virtualDesktopGeometries.remove(desktopId)) {
+        return;
+    }
+
+    const auto clientResources = resourceMap();
+    for (auto resource : clientResources) {
+        if (resource->version() < ORG_KDE_PLASMA_WINDOW_VIRTUAL_DESKTOP_GEOMETRY_SINCE_VERSION) {
+            continue;
+        }
+        send_virtual_desktop_geometry(resource->handle, desktopId, geometry.x(), geometry.y(), geometry.width(), geometry.height());
+    }
+}
+
 }

