+++ b/src/window.cpp
@@ -1835,6 +1835,16 @@ void Window::setupWindowManagementInterface()
     });
     connect(this, &Window::frameGeometryChanged, w, [w, this]() {
         w->setGeometry(frameGeometry().toRect());
+        updateVirtualDesktopGeometries();
+    });
+    connect(this, &Window::requestedTileChanged, w, [this]() {
+        updateVirtualDesktopGeometries();
+    });
+    connect(this, &Window::desktopsChanged, w, [this]() {
+        updateVirtualDesktopGeometries();
+    });
+    connect(VirtualDesktopManager::self(), &VirtualDesktopManager::currentChanged, w, [this]() {
+        updateVirtualDesktopGeometries();
     });
     connect(this, &Window::clientGeometryChanged, w, [w, this]() {
         w->setClientGeometry(clientGeometry().toRect());
@@ -1950,6 +1960,41 @@ void Window::setupWindowManagementInterface()
     }

     m_windowManagementInterface = w;
+    updateVirtualDesktopGeometries();
+}
+
+void Window::updateVirtualDesktopGeometries()
+{
+    if (!m_windowManagementInterface || isDeleted()) {
+        return;
+    }
+
+    const Rect currentGeometry = frameGeometry().toRect();
+    VirtualDesktop *currentDesktop = VirtualDesktopManager::self()->currentDesktop(output());
+    const auto desktops = VirtualDesktopManager::self()->desktops();
+    for (VirtualDesktop *desktop : desktops) {
+        Rect geometry;
+        if (desktop != currentDesktop && isOnDesktop(desktop)) {
+            // Mirror what Workspace does with the window's tiles when switching to that desktop
+            Tile *tile = nullptr;
+            const auto outputs = workspace()->outputs();
+            for (LogicalOutput *tileOutput : outputs) {
+                TileManager *manager = workspace()->tileManager(tileOutput);
+                if (Tile *candidate = manager ? manager->tileForWindow(this, desktop) : nullptr) {
+                    tile = candidate;
+                }
+            }
+            if (tile) {
+                geometry = tile->windowGeometry().toRect();
+            } else if (m_requestedTile && geometryRestore().isValid()) {
+                geometry = geometryRestore().toRect();
+            }
+            if (geometry == currentGeometry) {
+                geometry = Rect();
+            }
+        }
+        m_windowManagementInterface->setVirtualDesktopGeometry(desktop->id(), geometry);
+    }
 }

 void Window::destroyWindowManagementInterface()
