 applets/pager/windowmodel.cpp | 6 +++++-
 1 file changed, 5 insertions(+), 1 deletion(-)

diff --git a/applets/pager/windowmodel.cpp b/applets/pager/windowmodel.cpp
index 00b8156e79..e038bb9744 100644
--- a/applets/pager/windowmodel.cpp
+++ b/applets/pager/windowmodel.cpp
@@ -43,6 +43,9 @@ WindowModel::WindowModel(PagerModel *parent)
         if (roles.contains(AbstractTasksModel::StackingOrder)) {
             Q_EMIT dataChanged(topLeft, bottomRight, {WindowModelRoles::PagerStackingOrder});
         }
+        if (roles.contains(AbstractTasksModel::VirtualDesktopGeometries)) {
+            Q_EMIT dataChanged(topLeft, bottomRight, {AbstractTasksModel::Geometry});
+        }
     });
 }

