     void activitiesChanged();
@@ -278,12 +280,26 @@ protected:
     {
         virtualDesktops.removeAll(id);
         Q_EMIT virtualDesktopLeft();
+        if (virtualDesktopGeometries.remove(id)) {
+            Q_EMIT virtualDesktopGeometriesChanged();
+        }
     }
     void org_kde_plasma_window_geometry(int32_t x, int32_t y, uint32_t width, uint32_t height) override
     {
         geometry = QRect(x, y, width, height);
         Q_EMIT geometryChanged();
     }
+    void org_kde_plasma_window_virtual_desktop_geometry(const QString &id, int32_t x, int32_t y, uint32_t width, uint32_t height) override
